"""Exact arithmetic for the p05 verifier (stdlib only).  Independent of qlib/.

* parse_q / parse_entry: exact rationals ("3", "-2/7", "0.125", 5) and Gaussian rationals
  ([re, im] pairs) from JSON.
* Matrices are lists of lists of Fraction (real field) or GQ (complex field).
* projector_from_span(V): the orthogonal projector V (V^dag V)^{-1} V^dag, exactly.
* strategy_value(...): <psi|W|psi> / <psi|psi> for the Bell operator W, two independent ways.
* Words: an element of the universal algebra generated by Alice's projectors A_1..A_mA and Bob's
  B_1..B_mB (idempotent, Alice commutes with Bob, no other relations).  Reduced words
  (alice tuple, bob tuple) without equal neighbours form a basis of that algebra.
* sos_identity(...): coefficients of sum_ij Y_ij w_i^dag w_j in that basis.
* ldl_pd(...): exact positive-definiteness test (fraction-free, small N).
"""
import re
from fractions import Fraction

MAX_DEN_BITS = 4096
MAX_NUM_BITS = 4096


class Invalid(Exception):
    pass


# ----------------------------------------------------------------------------- numbers

_DEC = re.compile(r"^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$")
_RAT = re.compile(r"^[+-]?\d+(/\d+)?$")


def parse_q(x):
    """Exact rational from an int, a "p/q" string or a decimal string. Floats are rejected."""
    if isinstance(x, bool):
        raise Invalid("booleans are not numbers")
    if isinstance(x, int):
        q = Fraction(x)
    elif isinstance(x, str):
        s = x.strip()
        if len(s) > 2000:
            raise Invalid("number too long")
        if _RAT.match(s):
            q = Fraction(s)
        elif _DEC.match(s):
            m = re.search(r"[eE]([+-]?\d+)$", s)
            if m and abs(int(m.group(1))) > 400:
                raise Invalid("exponent too large")
            if len(s) > 2000:
                raise Invalid("number too long")
            q = Fraction(s)
        else:
            raise Invalid(f"not an exact number: {x!r}")
    else:
        raise Invalid(f"numbers must be ints or strings (exact), got {type(x).__name__}: {x!r}")
    if q.denominator.bit_length() > MAX_DEN_BITS or abs(q.numerator).bit_length() > MAX_NUM_BITS:
        raise Invalid("number too large")
    return q


class GQ:
    """Gaussian rational re + i*im."""
    __slots__ = ("re", "im")

    def __init__(self, re_, im_=Fraction(0)):
        self.re, self.im = re_, im_

    def __add__(self, o):
        return GQ(self.re + o.re, self.im + o.im)

    def __sub__(self, o):
        return GQ(self.re - o.re, self.im - o.im)

    def __mul__(self, o):
        return GQ(self.re * o.re - self.im * o.im, self.re * o.im + self.im * o.re)

    def __neg__(self):
        return GQ(-self.re, -self.im)

    def conj(self):
        return GQ(self.re, -self.im)

    def inv(self):
        n = self.re * self.re + self.im * self.im
        if n == 0:
            raise ZeroDivisionError
        return GQ(self.re / n, -self.im / n)

    def __truediv__(self, o):
        return self * o.inv()

    def is_zero(self):
        return self.re == 0 and self.im == 0

    def __eq__(self, o):
        return isinstance(o, GQ) and self.re == o.re and self.im == o.im

    def __repr__(self):
        return f"({self.re}+{self.im}i)"


class Field:
    """Real (Fraction) or complex (GQ) scalar operations behind one interface."""

    def __init__(self, kind):
        if kind not in ("real", "complex"):
            raise Invalid("field must be 'real' or 'complex'")
        self.kind = kind
        self.zero = Fraction(0) if kind == "real" else GQ(Fraction(0))
        self.one = Fraction(1) if kind == "real" else GQ(Fraction(1))

    def parse(self, x):
        if self.kind == "real":
            if isinstance(x, list):
                raise Invalid("complex entry in a real strategy")
            return parse_q(x)
        if isinstance(x, list):
            if len(x) != 2:
                raise Invalid("complex entries are [re, im] pairs")
            return GQ(parse_q(x[0]), parse_q(x[1]))
        return GQ(parse_q(x))

    def conj(self, a):
        return a if self.kind == "real" else a.conj()

    def is_zero(self, a):
        return a == 0 if self.kind == "real" else a.is_zero()

    def inv(self, a):
        return 1 / a if self.kind == "real" else a.inv()

    def real(self, a):
        return a if self.kind == "real" else a.re

    def imag(self, a):
        return Fraction(0) if self.kind == "real" else a.im


# ----------------------------------------------------------------------------- matrices

def mat_mul(F, X, Y):
    n, k, m = len(X), len(Y), len(Y[0]) if Y else 0
    out = []
    for i in range(n):
        Xi = X[i]
        row = []
        for j in range(m):
            s = F.zero
            for t in range(k):
                a = Xi[t]
                if not F.is_zero(a):
                    b = Y[t][j]
                    if not F.is_zero(b):
                        s = s + a * b
            row.append(s)
        out.append(row)
    return out


def dagger(F, X):
    return [[F.conj(X[i][j]) for i in range(len(X))] for j in range(len(X[0]))]


def transpose(X):
    return [list(r) for r in zip(*X)]


def mat_inv(F, M):
    """Exact inverse by Gauss-Jordan; raises Invalid if singular."""
    n = len(M)
    A = [list(M[i]) + [F.one if i == j else F.zero for j in range(n)] for i in range(n)]
    for c in range(n):
        piv = next((r for r in range(c, n) if not F.is_zero(A[r][c])), None)
        if piv is None:
            raise Invalid("spanning vectors are linearly dependent")
        A[c], A[piv] = A[piv], A[c]
        inv = F.inv(A[c][c])
        A[c] = [a * inv for a in A[c]]
        for r in range(n):
            if r != c and not F.is_zero(A[r][c]):
                f = A[r][c]
                A[r] = [a - f * b for a, b in zip(A[r], A[c])]
    return [row[n:] for row in A]


def projector_from_span(F, vecs, d):
    """vecs: list of r vectors of length d (exact). Returns the d x d projector onto their span."""
    if not vecs:
        return [[F.zero] * d for _ in range(d)]
    for v in vecs:
        if len(v) != d:
            raise Invalid(f"spanning vector of length {len(v)}, expected {d}")
    V = [[vecs[k][i] for k in range(len(vecs))] for i in range(d)]  # d x r, columns = vectors
    Vd = dagger(F, V)
    G = mat_mul(F, Vd, V)
    P = mat_mul(F, mat_mul(F, V, mat_inv(F, G)), Vd)
    return P


def is_projector(F, P):
    d = len(P)
    if any(P[i][j] != F.conj(P[j][i]) for i in range(d) for j in range(d)):
        return False
    return mat_mul(F, P, P) == P


# ----------------------------------------------------------------------------- strategy value

def strategy_value(F, ineq, A, B, psi, dA, dB):
    """Exact Bell value <psi|W|psi>/<psi|psi> via the reduced-state formula
    <psi| P (x) Q |psi> = Tr(P R Q^T R^dag), R[a][b] = psi[a*dB + b]."""
    mA, mB = ineq["mA"], ineq["mB"]
    R = [[psi[a * dB + b] for b in range(dB)] for a in range(dA)]
    Rd = dagger(F, R)
    S_I = mat_mul(F, R, Rd)
    S = [mat_mul(F, mat_mul(F, R, transpose(B[y])), Rd) for y in range(mB)]
    norm = F.real(trace(F, S_I))
    if norm == 0:
        raise Invalid("state vector is zero")

    def tr_prod(P, Sm):  # Tr(P Sm)
        s = F.zero
        for i in range(dA):
            for j in range(dA):
                if not F.is_zero(P[i][j]):
                    s = s + P[i][j] * Sm[j][i]
        return s
    val = F.zero
    for x in range(mA):
        tPI = tr_prod(A[x], S_I)
        val = val + tPI * F.parse(ineq["bA"][x])
        for y in range(mB):
            c = ineq["bAB"][x][y]
            if c:
                val = val + tr_prod(A[x], S[y]) * F.parse(c)
    for y in range(mB):
        val = val + trace(F, S[y]) * F.parse(ineq["bB"][y])
    if F.imag(val) != 0:
        raise Invalid("Bell value has an imaginary part (non-Hermitian input?)")
    return F.real(val) / norm


def strategy_value_bob(F, ineq, A, B, psi, dA, dB):
    """Independent re-check for large dimensions: Bob-side reduced formula
    <psi| P (x) Q |psi> = Tr(Q R^T P^T conj(R)), contracting over Alice's index first."""
    mA, mB = ineq["mA"], ineq["mB"]
    R = [[psi[a * dB + b] for b in range(dB)] for a in range(dA)]
    Rt = transpose(R)
    Rc = [[F.conj(z) for z in row] for row in R]
    T_I = mat_mul(F, Rt, Rc)                                   # Alice operator = identity
    T = [mat_mul(F, mat_mul(F, Rt, transpose(A[x])), Rc) for x in range(mA)]

    def tr_prod(Q, Tm):  # Tr(Q Tm)
        s = F.zero
        for i in range(dB):
            for j in range(dB):
                if not F.is_zero(Q[i][j]):
                    s = s + Q[i][j] * Tm[j][i]
        return s
    norm = F.real(trace(F, T_I))
    if norm == 0:
        raise Invalid("state vector is zero")
    val = F.zero
    for y in range(mB):
        val = val + tr_prod(B[y], T_I) * F.parse(ineq["bB"][y])
        for x in range(mA):
            c = ineq["bAB"][x][y]
            if c:
                val = val + tr_prod(B[y], T[x]) * F.parse(c)
    for x in range(mA):
        val = val + trace(F, T[x]) * F.parse(ineq["bA"][x])
    if F.imag(val) != 0:
        raise Invalid("Bell value has an imaginary part (non-Hermitian input?)")
    return F.real(val) / norm


def strategy_value_kron(F, ineq, A, B, psi, dA, dB):
    """Independent re-check: build W = sum c (A_x (x) B_y) entrywise and evaluate <psi|W|psi>."""
    mA, mB = ineq["mA"], ineq["mB"]
    n = dA * dB
    num = F.zero
    cA = [F.parse(v) for v in ineq["bA"]]
    cB = [F.parse(v) for v in ineq["bB"]]
    cAB = [[F.parse(v) for v in row] for row in ineq["bAB"]]
    # Alice-side operators X_y-independent pieces: M_A = sum_x cA[x] A_x, and per y: N_y = sum_x cAB[x][y] A_x
    MA = [[sum((cA[x] * A[x][i][j] for x in range(mA)), F.zero) for j in range(dA)] for i in range(dA)]
    NY = [[[sum((cAB[x][y] * A[x][i][j] for x in range(mA)), F.zero) for j in range(dA)] for i in range(dA)]
          for y in range(mB)]
    MB = [[sum((cB[y] * B[y][i][j] for y in range(mB)), F.zero) for j in range(dB)] for i in range(dB)]
    for r in range(n):
        a, b = divmod(r, dB)
        pr = F.conj(psi[r])
        if F.is_zero(pr):
            continue
        for s_ in range(n):
            a2, b2 = divmod(s_, dB)
            ps = psi[s_]
            if F.is_zero(ps):
                continue
            w = F.zero
            if b == b2:
                w = w + MA[a][a2]
            if a == a2:
                w = w + MB[b][b2]
            for y in range(mB):
                if not F.is_zero(NY[y][a][a2]) and not F.is_zero(B[y][b][b2]):
                    w = w + NY[y][a][a2] * B[y][b][b2]
            if not F.is_zero(w):
                num = num + pr * w * ps
    den = F.zero
    for r in range(n):
        den = den + F.conj(psi[r]) * psi[r]
    if F.imag(num) != 0 or F.imag(den) != 0:
        raise Invalid("Bell value has an imaginary part")
    return F.real(num) / F.real(den)


def trace(F, M):
    s = F.zero
    for i in range(len(M)):
        s = s + M[i][i]
    return s


# ----------------------------------------------------------------------------- words and SOS

_TOK = re.compile(r"([AB])(\d+)")


def parse_word(s, mA, mB):
    """'A1A3B2' (1-based settings) -> reduced (alice tuple, bob tuple) with 0-based settings."""
    if not isinstance(s, str):
        raise Invalid("words must be strings like 'A1B2'")
    t = s.replace(" ", "").replace("*", "")
    if _TOK.sub("", t):
        raise Invalid(f"bad word {s!r}")
    a, b = [], []
    for p, k in _TOK.findall(t):
        k = int(k)
        if p == "A":
            if not 1 <= k <= mA:
                raise Invalid(f"setting A{k} out of range in {s!r}")
            a.append(k - 1)
        else:
            if not 1 <= k <= mB:
                raise Invalid(f"setting B{k} out of range in {s!r}")
            b.append(k - 1)
    return (collapse(a), collapse(b))


def collapse(seq):
    out = []
    for s in seq:
        if not out or out[-1] != s:
            out.append(s)
    return tuple(out)


def dag_mul(u, v):
    """Normal form of u^dagger v."""
    return (collapse(tuple(reversed(u[0])) + v[0]), collapse(tuple(reversed(u[1])) + v[1]))


def sos_identity(words, Ynum):
    """Return {reduced word: integer coefficient} of sum_ij Ynum[i][j] w_i^dag w_j (Ynum symmetric)."""
    coef = {}
    n = len(words)
    for i in range(n):
        wi = words[i]
        row = Ynum[i]
        for j in range(n):
            v = row[j]
            if v:
                m = dag_mul(wi, words[j])
                coef[m] = coef.get(m, 0) + v
    return coef


def bell_polynomial(ineq):
    """{word: Fraction} of the Bell operator B."""
    p = {}
    for x in range(ineq["mA"]):
        if ineq["bA"][x]:
            p[((x,), ())] = Fraction(ineq["bA"][x])
        for y in range(ineq["mB"]):
            if ineq["bAB"][x][y]:
                p[((x,), (y,))] = Fraction(ineq["bAB"][x][y])
    for y in range(ineq["mB"]):
        if ineq["bB"][y]:
            p[((), (y,))] = Fraction(ineq["bB"][y])
    return p


def ldl_pd(Ynum):
    """Exact test that the integer symmetric matrix Ynum is positive definite (Bareiss)."""
    n = len(Ynum)
    A = [list(r) for r in Ynum]
    prev = 1
    for k in range(n):
        if A[k][k] <= 0:
            return False
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * A[k][k] - A[i][k] * A[k][j]) // prev
        prev = A[k][k]
    return True
